--------------------------------------------------------------------------------
-- mire_pkg : mire 16 couleurs 352 × 288 (indices 4 bits, un caractère
--   hexadécimal par pixel) et palette Y, Cb, Cr ; frontières de
--   couleur sur coordonnées paires, la chrominance 4:2:0 d'un bloc
--   2 × 2 est donc celle de la palette
--   (fichier généré par fpga_test/mire.js ; même image : fpga_test/mire.png)
--------------------------------------------------------------------------------
context work.jpeg2dvb_ctx;

package mire_pkg is
    constant MIRE_L : natural := 352;
    constant MIRE_H : natural := 288;
    type ycc_t is array (0 to 2) of natural range 0 to 255;
    type palette_t is array (0 to 15) of ycc_t;
    constant PALETTE : palette_t := (
         0 => (255, 128, 128),
         1 => (226, 1, 149),
         2 => (179, 171, 1),
         3 => (150, 44, 21),
         4 => (105, 212, 235),
         5 => (76, 85, 255),
         6 => (29, 255, 107),
         7 => (0, 128, 128),
         8 => (36, 128, 128),
         9 => (73, 128, 128),
        10 => (109, 128, 128),
        11 => (146, 128, 128),
        12 => (182, 128, 128),
        13 => (219, 128, 128),
        14 => (176, 62, 174),
        15 => (32, 134, 122));
